#!/usr/bin/env python3
"""Generate the bilingual game catalog sections in the repository READMEs."""

from __future__ import annotations

import argparse
import configparser
import difflib
import re
import sys
import tomllib
from pathlib import Path
from typing import Any


BEGIN_MARKER = (
    "<!-- BEGIN:games (auto-generated by scripts/gen_catalog.py — "
    "edit games.toml then re-run) -->"
)
END_MARKER = "<!-- END:games -->"
MARKER_BLOCK = re.compile(
    r"^<!-- BEGIN:games[^\r\n]*(?:\r?\n).*?^<!-- END:games -->[ \t]*$",
    re.MULTILINE | re.DOTALL,
)
KEY_PATTERN = re.compile(r"^rs-[a-z0-9]+(?:-[a-z0-9]+)*$")
REQUIRED_KEYS = ("key", "title", "title_ja", "summary", "summary_ja", "tags")


class CatalogError(Exception):
    """An input or repository-layout error that should be shown without a traceback."""


def read_text_exact(path: Path) -> str:
    try:
        with path.open("r", encoding="utf-8", newline="") as handle:
            return handle.read()
    except OSError as exc:
        raise CatalogError(f"{path.name}: {exc}") from exc


def load_games(root: Path) -> list[dict[str, Any]]:
    path = root / "games.toml"
    try:
        with path.open("rb") as handle:
            document = tomllib.load(handle)
    except (OSError, tomllib.TOMLDecodeError) as exc:
        raise CatalogError(f"games.toml: {exc}") from exc

    games = document.get("games")
    if not isinstance(games, list):
        raise CatalogError("games.toml: top-level [[games]] entries are required")

    validated: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, game in enumerate(games, start=1):
        if not isinstance(game, dict):
            raise CatalogError(f"games.toml: game #{index} (<unknown>): entry must be a table")
        key_value = game.get("key", "<unknown>")
        label = str(key_value)
        prefix = f"games.toml: game #{index} ({label})"
        missing = [name for name in REQUIRED_KEYS if name not in game]
        if missing:
            raise CatalogError(f"{prefix}: missing required key: {missing[0]}")
        if not isinstance(key_value, str) or not KEY_PATTERN.fullmatch(key_value):
            raise CatalogError(f"{prefix}: invalid key; expected rs-prefixed kebab-case")
        if key_value in seen:
            raise CatalogError(f"{prefix}: duplicate key: {key_value}")
        for name in ("title", "title_ja", "summary", "summary_ja"):
            if not isinstance(game[name], str):
                raise CatalogError(f"{prefix}: {name} must be a string")
        tags = game["tags"]
        if not isinstance(tags, list) or any(not isinstance(tag, str) for tag in tags):
            raise CatalogError(f"{prefix}: tags must be an array of strings")
        seen.add(key_value)
        validated.append(game)
    return validated


def validate_gitmodules(root: Path, games: list[dict[str, Any]]) -> None:
    path = root / ".gitmodules"
    if not path.exists():
        return

    parser = configparser.ConfigParser(interpolation=None)
    try:
        parser.read_string(read_text_exact(path))
    except configparser.Error as exc:
        raise CatalogError(f".gitmodules: {exc}") from exc

    submodule_paths = {
        parser.get(section, "path")
        for section in parser.sections()
        if section.startswith("submodule ") and parser.has_option(section, "path")
    }
    catalog_paths = {f"games/{game['key']}" for game in games}
    errors: list[str] = []
    for game in games:
        expected = f"games/{game['key']}"
        if expected not in submodule_paths:
            errors.append(
                f".gitmodules: missing submodule path for games.toml game "
                f"{game['key']}: {expected}"
            )
    for submodule_path in sorted(submodule_paths):
        if submodule_path.startswith("games/") and submodule_path not in catalog_paths:
            errors.append(
                ".gitmodules: submodule under games/ is not listed in games.toml: "
                f"{submodule_path}"
            )
    if errors:
        raise CatalogError("\n".join(errors))


def escape_cell(value: str) -> str:
    return value.replace("|", r"\|")


def tags_cell(tags: list[str]) -> str:
    return " ".join(f"`{escape_cell(tag)}`" for tag in tags)


def render_catalog(games: list[dict[str, Any]], *, japanese: bool) -> str:
    count = len(games)
    if japanese:
        lines = [
            BEGIN_MARKER,
            "",
            f"{count} 本のゲームを収録しています．",
            "",
            "| ゲーム | 概要 | タグ | リポジトリ |",
            "|---|---|---|---|",
        ]
    else:
        lines = [
            BEGIN_MARKER,
            "",
            f"{count} game(s).",
            "",
            "| Game | Summary | Tags | Repo |",
            "|---|---|---|---|",
        ]

    # Link to the game's own repository: a relative link to the submodule path
    # (games/<key>) becomes blob/main/games/<key> on GitHub, which is a 404.
    for game in games:
        key = game["key"]
        title = game["title_ja"] if japanese else game["title"]
        summary = game["summary_ja"] if japanese else game["summary"]
        lines.append(
            f"| [{escape_cell(title)}](https://github.com/akitenkrad/{key}) | {escape_cell(summary)} | "
            f"{tags_cell(game['tags'])} | "
            f"[{key}](https://github.com/akitenkrad/{key}) |"
        )
    lines.extend(("", END_MARKER))
    return "\n".join(lines)


def replace_catalog(path: Path, current: str, generated: str) -> str:
    matches = list(MARKER_BLOCK.finditer(current))
    if len(matches) != 1:
        raise CatalogError(f"{path.name}: games catalog markers not found or not unique")
    match = matches[0]
    return current[: match.start()] + generated + current[match.end() :]


def show_diff(path: Path, current: str, generated: str) -> None:
    diff = difflib.unified_diff(
        current.splitlines(keepends=True),
        generated.splitlines(keepends=True),
        fromfile=f"{path.name} (current)",
        tofile=f"{path.name} (generated)",
    )
    sys.stdout.writelines(diff)
    if current and generated and not generated.endswith("\n"):
        sys.stdout.flush()


def write_text_exact(path: Path, contents: str) -> None:
    with path.open("w", encoding="utf-8", newline="") as handle:
        handle.write(contents)


def generate(root: Path, *, check: bool) -> bool:
    games = load_games(root)
    validate_gitmodules(root, games)

    planned: list[tuple[Path, str, str]] = []
    for filename, japanese in (("README.md", False), ("README.ja.md", True)):
        path = root / filename
        current = read_text_exact(path)
        updated = replace_catalog(path, current, render_catalog(games, japanese=japanese))
        planned.append((path, current, updated))

    changed = [(path, current, updated) for path, current, updated in planned if current != updated]
    if check:
        for path, current, updated in changed:
            show_diff(path, current, updated)
        return not changed

    for path, _current, updated in changed:
        write_text_exact(path, updated)
    return True


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    default_root = Path(__file__).resolve().parent.parent
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="show drift without writing files")
    parser.add_argument("--root", type=Path, default=default_root, help="repository root")
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    try:
        return 0 if generate(args.root.resolve(), check=args.check) else 1
    except CatalogError as exc:
        print(exc, file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
